SELECT *
FROM crm_lead

    deleted = '0'


            AND lead_name LIKE CONCAT('%', #{query.leadName}, '%')


            AND company_name LIKE CONCAT('%', #{query.companyName}, '%')


            AND contact_name LIKE CONCAT('%', #{query.contactName}, '%')


            AND mobile LIKE CONCAT('%', #{query.mobile}, '%')


            AND status = #{query.status}


            AND owner_id = #{query.ownerId}

        AND qualification_status = #{query.qualificationStatus}
        AND territory_id = #{query.territoryId}
        AND market_segment = #{query.marketSegment}
        AND industry = #{query.industry}
        AND campaign_id = #{query.campaignId}
        AND lead_score >= #{query.scoreMin}
        AND lead_score <= #{query.scoreMax}


ORDER BY lead_score DESC,
         lead_score ASC, update_time DESC, lead_id DESC
